/**
 * Browsable view of an arbitrary JSON value (`design/components/json-tree.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/json-tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  claimSlot,
  elementRef,
  jsonTreeBranches,
  jsonTreeExpanded,
  scope,
  setJsonTreeBranch,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/json-tree.module.css'
import JsonTreeEntry from './JsonTreeEntry'

export interface JsonTreeProps {
  /**
   * Any JSON value; `undefined` and other non-JSON values render as their `String()` form rather
   * than crashing a page that already has a bug.
   */
  data: unknown
  /**
   * Levels open at mount (`0` all closed, `Infinity` for payloads known to be small);
   * uncontrolled afterwards, because browsing is not app state.
   */
  defaultDepth?: number
  /**
   * The tree's accessible name, such as "Response body" rather than "JSON".
   */
  label: string
}

/** Browsable view of an arbitrary JSON value. */
export default function JsonTree(given: JsonTreeProps): JSX.Element {
  const props = mergeProps(
    { defaultDepth: 1 } as Defaults<JsonTreeProps, 'defaultDepth'>,
    claimSlot(given),
  )
  return scope(() => {
    const tree = elementRef<HTMLElement>()
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'JsonTree',
        element: () => tree.value,
        state: () => ({
          expanded: jsonTreeExpanded(tree.value, styles.toggle, styles.key),
          branches: jsonTreeBranches(tree.value, styles.toggle, styles.key),
        }),
        actions: {
          expand: {
            argument: 'id',
            run: (value) => setJsonTreeBranch(tree.value, styles.toggle, styles.key, value, true),
          },
          collapse: {
            argument: 'id',
            run: (value) => setJsonTreeBranch(tree.value, styles.toggle, styles.key, value, false),
          },
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <ul class={styles.root} aria-label={props.label} data-member="json-tree" ref={tree.attach}>
        <JsonTreeEntry value={props.data} depth={0} defaultDepth={props.defaultDepth} />
      </ul>
    )
  })
}
